import java.util.*;

public class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> res = new ArrayList<>();
        if (s == null || s.length() == 0 || words == null || words.length == 0) return res;

        int wordLen = words[0].length();
        int wordCount = words.length;
        int totalLen = wordLen * wordCount;
        if (s.length() < totalLen) return res;

        Map<String, Integer> need = new HashMap<>();
        for (String w : words) need.put(w, need.getOrDefault(w, 0) + 1);

        // Slide with offsets 0..wordLen-1
        for (int offset = 0; offset < wordLen; offset++) {
            int left = offset;
            int matched = 0;
            Map<String, Integer> window = new HashMap<>();
            for (int j = offset; j + wordLen <= s.length(); j += wordLen) {
                String word = s.substring(j, j + wordLen);
                if (need.containsKey(word)) {
                    window.put(word, window.getOrDefault(word, 0) + 1);
                    matched++;

                    // If word count exceeds needed, move left to reduce
                    while (window.get(word) > need.get(word)) {
                        String leftWord = s.substring(left, left + wordLen);
                        window.put(leftWord, window.get(leftWord) - 1);
                        matched--;
                        left += wordLen;
                    }

                    // If we've matched the required number of words, record answer
                    if (matched == wordCount) {
                        res.add(left);
                        // Move left one word forward to continue searching
                        String leftWord = s.substring(left, left + wordLen);
                        window.put(leftWord, window.get(leftWord) - 1);
                        matched--;
                        left += wordLen;
                    }
                } else {
                    // Reset window
                    window.clear();
                    matched = 0;
                    left = j + wordLen;
                }
            }
        }

        return res;
    }
}

